benchmark_problem:
In the diagram, $D$ and $E$ are the midpoints of $\overline{AB}$ and $\overline{BC}$ respectively.  Determine the area of quadrilateral $DBEF$. [asy]
size(180); defaultpen(linewidth(.7pt)+fontsize(10pt));
pair A, B, C, D, E, F;
A=(0,6);
B=(0,0);
C=(8,0);
D=(0,3);
E=(4,0);
F=(8/3,2);
draw(E--A--C--D);
draw((-1,0)--(10,0), EndArrow);
draw((0,-1)--(0,8), EndArrow);
label("$A(0,6)$", A, W);
label("$B(0,0)$", B, SW);
label("$C(8,0)$", C, S);
label("$D$", D, W);
label("$E$", E, S);
label("$F$", F, SW);
label("$x$", (10,0), dir(0));
label("$y$", (0,8), dir(90));
[/asy]

Find the number of triples of nonnegative integers \((a,b,c)\) satisfying \(a + b + c = 300\) and
\begin{equation*}
a^2b + a^2c + b^2a + b^2c + c^2a + c^2b = 6,000,000.
\end{equation*}

training_problem:
In the magic square shown, the sums of the numbers in each row, column, and diagonal are the same. Five of these numbers are represented by $v$, $w$, $x$, $y$, and $z$. Find $y+z$.

[asy]
path a=(0,0)--(1,0)--(1,1)--(0,1)--cycle;
for (int i=0; i<3; ++i) {
for (int j=0; j<3; ++j) {
draw(shift((i,j))*a);
};}
label("25",(0.5,0.3),N);
label("$z$",(1.5,0.3),N);
label("21",(2.5,0.3),N);
label("18",(0.5,1.3),N);
label("$x$",(1.5,1.3),N);
label("$y$",(2.5,1.3),N);
label("$v$",(0.5,2.3),N);
label("24",(1.5,2.3),N);
label("$w$",(2.5,2.3),N);
[/asy]

benchmark_problem:
A set of three points is chosen randomly from the grid shown. Each three-point set has the same probability of being chosen. What is the probability that the points lie on the same straight line?

[asy]
size(50);
for (int i=0; i<3; ++i) {
for (int j=0; j<3; ++j) {
dot((i,j));};}
[/asy]

